package net.officefloor.hq.app.pool;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** The pools on a sheet: each a name and its members, people of the sheet with a share percent. */
@Service
public class PoolService {

    private static final BigDecimal HUNDRED = new BigDecimal("100.00");

    /** A pool with its members, in the order they were added. */
    public record PoolWithMembers(Pool pool, List<PoolMember> members) {
    }

    private final PoolRepository pools;
    private final PoolMemberRepository members;
    private final PersonRepository people;
    private final SheetService sheets;
    private final Audit audit;

    public PoolService(PoolRepository pools, PoolMemberRepository members, PersonRepository people,
            SheetService sheets, Audit audit) {
        this.pools = pools;
        this.members = members;
        this.people = people;
        this.sheets = sheets;
        this.audit = audit;
    }

    /** The sheet's pools, in the order they were added, each with its members. */
    public List<PoolWithMembers> list(String sheetId) {
        List<Pool> list = pools.findBySheetIdOrderByIdAsc(sheetId);
        Map<Long, List<PoolMember>> byPool = members
                .findByPoolIdInOrderByIdAsc(list.stream().map(Pool::getId).toList()).stream()
                .collect(Collectors.groupingBy(PoolMember::getPoolId));
        return list.stream().map(p -> new PoolWithMembers(p, byPool.getOrDefault(p.getId(), List.of()))).toList();
    }

    /** Add a pool, its name trimmed. Refused when the name is blank or already a pool's on the sheet.
     *  The sheet is held locked so the same name added at the same moment is checked against itself. */
    @Transactional
    public PoolWithMembers add(String sheetId, String user, String name) {
        String key = name == null ? "" : name.trim();
        if (key.isEmpty()) {
            throw new PoolRefusedException("A pool needs a name");
        }
        sheets.lock(sheetId);
        if (pools.existsBySheetIdAndName(sheetId, key)) {
            throw new PoolRefusedException("The pool " + key + " is on the sheet already");
        }
        Pool saved = pools.saveAndFlush(new Pool(sheetId, key));
        audit.recordOnCommit("POOL_ADDED sheet=" + sheetId + " by=" + user + " name=" + key);
        return new PoolWithMembers(saved, List.of());
    }

    /** Add a person of the sheet to a pool with a share percent: more than 0.00 and at most 100.00,
     *  with up to two decimals. Refused for a person already in the pool, or such a share. */
    @Transactional
    public PoolWithMembers addMember(String sheetId, String user, Long poolId, Long personId, BigDecimal share) {
        if (share == null || share.signum() <= 0 || share.compareTo(HUNDRED) > 0
                || share.stripTrailingZeros().scale() > 2) {
            throw new PoolRefusedException("A share is more than 0.00 and at most 100.00, with two decimals");
        }
        BigDecimal scaled = share.setScale(2, RoundingMode.UNNECESSARY);
        sheets.lock(sheetId);
        Pool pool = pools.findByIdAndSheetId(poolId, sheetId)
                .orElseThrow(() -> new PoolRefusedException("No such pool on the sheet"));
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new PoolRefusedException("No such person on the sheet"));
        if (members.existsByPoolIdAndPersonId(poolId, personId)) {
            throw new PoolRefusedException(person.getName() + " is in the pool " + pool.getName() + " already");
        }
        members.saveAndFlush(new PoolMember(poolId, personId, scaled));
        audit.recordOnCommit("POOL_MEMBER_ADDED sheet=" + sheetId + " by=" + user + " pool=" + pool.getName()
                + " name=" + person.getName() + " share=" + scaled.toPlainString());
        return new PoolWithMembers(pool, members.findByPoolIdInOrderByIdAsc(List.of(poolId)));
    }
}
import { HttpClient } from '@angular/common/http';
import { Component, Injectable, computed, effect, inject, input, signal } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Session } from '../../core/session';
import { SettingStore } from '../settings/settings';

export interface PoolMember {
  personId: number;
  /** The member's share percent (two decimals). */
  share: string;
}

export interface Pool {
  id: number;
  /** The pool's name, trimmed; unique on the sheet, it names the pool's row. */
  name: string;
  /** The pool's members, in the order they were added. */
  members: PoolMember[];
}

/** A person as a pool shows them: their name, and whether a retirement date is set. */
export interface PoolPerson {
  id: number;
  name: string;
  retired: boolean;
}

/** Hundredths in a two-decimal figure ("33.33" is 3333). */
function hundredths(figure: string): bigint {
  const [whole, part = ''] = figure.split('.');
  return BigInt(whole) * 100n + BigInt(part.padEnd(2, '0').slice(0, 2));
}

/** Hundredths as a two-decimal figure. */
function figure(hundredths: bigint): string {
  const sign = hundredths < 0n ? '-' : '';
  const abs = hundredths < 0n ? -hundredths : hundredths;
  return `${sign}${abs / 100n}.${String(abs % 100n).padStart(2, '0')}`;
}

/** Each member's cut of the pot in hundredths, in the members' order: the pot times their share
 *  divided by 100, rounded half to even; a retired member's 0. The remainder, the pot minus the cuts
 *  added up, goes to the member with the largest share, the earliest added on a tie. */
function cuts(pot: bigint, members: { share: bigint; retired: boolean }[]): bigint[] {
  const list = members.map((m) => {
    if (m.retired) return 0n;
    const exact = pot * m.share; // in ten-thousandths of a hundredth
    let cut = exact / 10000n;
    const rest = exact % 10000n;
    if (rest > 5000n || (rest === 5000n && cut % 2n === 1n)) cut += 1n;
    return cut;
  });
  let largest = -1;
  members.forEach((m, i) => {
    if (!m.retired && (largest < 0 || m.share > members[largest].share)) largest = i;
  });
  if (largest >= 0) list[largest] += pot - list.reduce((sum, c) => sum + c, 0n);
  return list;
}

/** A share (two decimals, more than 0.00 and at most 100.00). */
const SHARE = /^\d{1,3}(\.\d{1,2})?$/;

// The active sheet's pools, in the order they were added, re-read whenever a sheet is loaded.
@Injectable({ providedIn: 'root' })
export class PoolStore {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  readonly pools = signal<Pool[]>([]);

  constructor() {
    effect(() => {
      const sheet = this.session.sheetId();
      const load = this.session.loads();
      this.pools.set([]);
      if (sheet) void this.read(sheet, load);
    });
  }

  /** Add a pool to the active sheet; the server refuses a blank name or one already a pool's. */
  async add(name: string): Promise<void> {
    const sheet = this.session.sheetId();
    if (!sheet) throw new Error('No sheet loaded.');
    const saved = await firstValueFrom(this.http.post<Pool>(`${this.base(sheet)}`, { name }));
    this.keep(sheet, saved);
  }

  /** Add a person to a pool with a share; the server refuses a person already in it, or a bad share. */
  async addMember(poolId: number, personId: number, share: string): Promise<void> {
    const sheet = this.session.sheetId();
    if (!sheet) throw new Error('No sheet loaded.');
    const saved = await firstValueFrom(
      this.http.post<Pool>(`${this.base(sheet)}/${poolId}/members`, { personId, share }),
    );
    this.keep(sheet, saved);
  }

  private base(sheet: string): string {
    return `/api/sheets/${encodeURIComponent(sheet)}/pools`;
  }

  /** Show a pool as saved, in its place, or last when it is new. */
  private keep(sheet: string, saved: Pool): void {
    if (this.session.sheetId() !== sheet) return;
    this.pools.update((list) =>
      list.some((p) => p.id === saved.id) ? list.map((p) => (p.id === saved.id ? saved : p)) : [...list, saved],
    );
  }

  private async read(sheet: string, load: number): Promise<void> {
    const list = await firstValueFrom(this.http.get<Pool[]>(this.base(sheet)));
    if (this.session.loads() !== load) return;
    this.pools.set(list);
  }
}

/** A pool as its row shows it: its members with their names, its total share and whether it balances. */
interface PoolRow {
  pool: Pool;
  /** Each member with their cut of the pot (two decimals); blank when the pool is unbalanced or
   *  there is no pot. */
  members: { personId: number; name: string; share: string; cut: string }[];
  /** The members' shares added up, a retired member's counting as 0.00 (two decimals). */
  total: string;
  /** Whether the total is exactly 100.00. */
  balanced: boolean;
}

// The sheet's pools, the form that adds one, and on each pool's row the entry that adds a member.
@Component({
  selector: 'app-pools',
  template: `
    <section aria-labelledby="pools-heading">
      <h2 id="pools-heading">Pools</h2>
      <form (submit)="submit($event)">
        <label for="pool-form-name">Pool name</label>
        <input
          id="pool-form-name"
          data-testid="pool-form-name"
          [value]="name()"
          (input)="name.set(value($event)); error.set(null)"
        />
        <button type="submit" data-testid="pool-form-submit">Add pool</button>
        @if (error(); as message) {
          <p role="alert" data-testid="pool-form-error">{{ message }}</p>
        }
      </form>
      <ul>
        @for (row of rows(); track row.pool.id) {
          <li [attr.data-testid]="'pool-row-' + row.pool.name">
            <h3>{{ row.pool.name }}</h3>
            <p>
              Total share <strong data-testid="pool-total-share">{{ row.total }}</strong>,
              balanced <strong data-testid="pool-balanced">{{ row.balanced ? 'yes' : 'no' }}</strong>
            </p>
            <ul>
              @for (m of row.members; track m.personId) {
                <li [attr.data-testid]="'pool-member-' + row.pool.name + '-' + m.personId">
                  {{ m.name }} <span data-testid="pool-share">{{ m.share }}</span>%, cut
                  <span data-testid="pool-cut">{{ m.cut }}</span>
                </li>
              }
            </ul>
            <label [for]="'pool-member-select-' + row.pool.id">Member</label>
            <select
              [id]="'pool-member-select-' + row.pool.id"
              data-testid="pool-member-select"
              (change)="setPerson(row.pool.id, value($event))"
            >
              <option value="" [selected]="!entries()[row.pool.id]?.personId">Choose a person</option>
              @for (p of people(); track p.id) {
                <option [value]="p.id" [selected]="entries()[row.pool.id]?.personId === '' + p.id">{{ p.name }}</option>
              }
            </select>
            <label [for]="'pool-member-share-' + row.pool.id">Share %</label>
            <input
              [id]="'pool-member-share-' + row.pool.id"
              data-testid="pool-member-share"
              [value]="entries()[row.pool.id]?.share ?? ''"
              (input)="setShare(row.pool.id, value($event))"
            />
            <button type="button" data-testid="pool-member-add" (click)="addMember(row.pool)">Add member</button>
            @if (memberErrors()[row.pool.id]; as message) {
              <p role="alert" data-testid="pool-error">{{ message }}</p>
            }
          </li>
        }
      </ul>
    </section>
  `,
})
export class Pools {
  /** The sheet's people, a member's name and retirement read from here. */
  readonly people = input.required<PoolPerson[]>();

  protected readonly store = inject(PoolStore);
  private readonly settings = inject(SettingStore);
  protected readonly name = signal('');
  protected readonly error = signal<string | null>(null);
  /** The person and share chosen on each pool's row, by pool id. */
  protected readonly entries = signal<Record<number, { personId?: string; share?: string }>>({});
  /** The error shown on each pool's row, by pool id. */
  protected readonly memberErrors = signal<Record<number, string | null>>({});
  /** Whether a submit is waiting for its answer; a second submit meanwhile is dropped. */
  private readonly busy = signal(false);

  protected readonly rows = computed<PoolRow[]>(() => {
    const byId = new Map(this.people().map((p) => [p.id, p]));
    const pot = this.settings.pot();
    return this.store.pools().map((pool) => {
      const shares = pool.members.map((m) => ({
        share: hundredths(m.share),
        retired: byId.get(m.personId)?.retired ?? false,
      }));
      const total = shares.filter((m) => !m.retired).reduce((sum, m) => sum + m.share, 0n);
      const balanced = total === 10000n;
      const cut = balanced && pot !== '' ? cuts(hundredths(pot), shares).map(figure) : null;
      const members = pool.members.map((m, i) => ({
        personId: m.personId,
        name: byId.get(m.personId)?.name ?? '',
        share: m.share,
        cut: cut ? cut[i] : '',
      }));
      return { pool, members, total: figure(total), balanced };
    });
  });

  protected value(event: Event): string {
    return (event.target as HTMLInputElement).value;
  }

  protected setPerson(poolId: number, personId: string): void {
    this.entries.update((e) => ({ ...e, [poolId]: { ...e[poolId], personId } }));
    this.memberErrors.update((e) => ({ ...e, [poolId]: null }));
  }

  protected setShare(poolId: number, share: string): void {
    this.entries.update((e) => ({ ...e, [poolId]: { ...e[poolId], share } }));
    this.memberErrors.update((e) => ({ ...e, [poolId]: null }));
  }

  /** Add the typed pool, its name trimmed; a blank name or one already a pool's is refused beside the form. */
  protected async submit(event: Event): Promise<void> {
    event.preventDefault();
    if (this.busy()) return;
    this.error.set(null);
    const name = this.name().trim();
    if (name === '') {
      this.error.set('Type a name for the pool.');
      return;
    }
    this.busy.set(true);
    try {
      await this.store.add(name);
    } catch {
      this.error.set(`The pool ${name} could not be added: the name may be a pool's already.`);
    } finally {
      this.busy.set(false);
    }
  }

  /** Add the chosen person with the typed share; a person already in the pool, or a share not more
   *  than 0.00 and at most 100.00 with two decimals, is refused on the pool's row. */
  protected async addMember(pool: Pool): Promise<void> {
    if (this.busy()) return;
    const refuse = (message: string) => this.memberErrors.update((e) => ({ ...e, [pool.id]: message }));
    this.memberErrors.update((e) => ({ ...e, [pool.id]: null }));
    const entry = this.entries()[pool.id] ?? {};
    const personId = Number(entry.personId);
    const share = (entry.share ?? '').trim();
    if (!entry.personId || !Number.isInteger(personId)) {
      refuse('Choose a person to add.');
      return;
    }
    if (!SHARE.test(share) || Number(share) <= 0 || Number(share) > 100) {
      refuse('A share is more than 0.00 and at most 100.00, with up to two decimals.');
      return;
    }
    if (pool.members.some((m) => m.personId === personId)) {
      refuse('That person is in the pool already.');
      return;
    }
    this.busy.set(true);
    try {
      await this.store.addMember(pool.id, personId, share);
    } catch {
      refuse('The member could not be added: they may be in the pool already.');
    } finally {
      this.busy.set(false);
    }
  }
}

